"""Phase 7: the report only formats validated snapshot values."""

import re
from datetime import UTC, datetime

import pytest
from phase7_helpers import MADE_AT

from stock_analysis.snapshots import (
    DISCLAIMER,
    ReportIntegrityError,
    build_forecast_snapshot,
    find_unsupported_numbers,
    render_forecast_report,
)
from stock_analysis.snapshots import report as report_module

REQUIRED_DISCLAIMER = (
    "This output is generated by an automated system for educational and demonstration "
    "purposes only. It is not investment advice, and forecasts are probabilistic estimates "
    "that may be wrong. Do not make financial decisions based on this output."
)

SECTIONS = [
    "## Prior context",
    "## Current analysis",
    "## Quant baseline",
    "## Decision-engine assessment",
    "## Final forecast",
    "## Forecast adjustments",
    "## Key drivers",
    "## Risks",
    "## Invalidation triggers",
    "## Data quality",
    "## Model and version information",
    "## Disclaimer",
]


@pytest.fixture(params=["adjusted_state", "fallback_state", "guardrail_state"])
def any_snapshot(request):
    return build_forecast_snapshot(request.getfixturevalue(request.param), made_at=MADE_AT)


class TestReportContent:
    def test_contains_all_sections_in_order(self, any_snapshot):
        report = render_forecast_report(any_snapshot)
        positions = [report.index(section) for section in SECTIONS]
        assert positions == sorted(positions)

    def test_ends_with_required_disclaimer_verbatim(self, any_snapshot):
        assert DISCLAIMER == REQUIRED_DISCLAIMER
        report = render_forecast_report(any_snapshot)
        assert report.rstrip().endswith(REQUIRED_DISCLAIMER)

    def test_shows_final_and_baseline_numbers(self, snapshot):
        report = render_forecast_report(snapshot)
        final, quant = snapshot.final_forecast, snapshot.quant_baseline
        assert f"₹{final.p50_price:.2f}" in report
        assert f"{final.prob_up * 100:.1f}%" in report
        assert f"{quant['prob_up'] * 100:.1f}%" in report
        assert snapshot.forecast_id in report
        assert snapshot.data_snapshot_id in report

    def test_lists_adjustments_with_evidence(self, snapshot):
        report = render_forecast_report(snapshot)
        adjustments = report.split("## Forecast adjustments")[1].split("## Key drivers")[0]
        assert "prob_up:" in adjustments
        assert "Constructive trend" in adjustments
        assert "Close above 20-day average" in adjustments

    def test_unadjusted_forecast_explains_gate(self, guardrail_state):
        snap = build_forecast_snapshot(guardrail_state, made_at=MADE_AT)
        report = render_forecast_report(snap)
        assert "No adjustment was applied" in report
        assert "no_adjustment" in report
        assert "Guardrail violation:" in report

    def test_includes_versions_and_risks(self, snapshot):
        report = render_forecast_report(snapshot)
        for key, value in snapshot.model_versions.items():
            assert f"Model `{key}`: {value}" in report
        for key, value in snapshot.prompt_versions.items():
            assert f"Prompt `{key}`: {value}" in report
        assert "Calibration version: 0" in report
        assert "Earnings surprise could reverse trend" in report
        assert "No intraday data" in report

    def test_correction_is_labelled(self, snapshot):
        corrected = snapshot.corrected(
            reason="Wrong company name",
            corrected_at=datetime(2026, 9, 30, tzinfo=UTC),
            company_name="Reliance Industries Limited",
        )
        report = render_forecast_report(corrected)
        assert f"Supersedes `{snapshot.forecast_id}`: Wrong company name" in report

    def test_no_trading_recommendation_language(self, any_snapshot):
        report = render_forecast_report(any_snapshot).lower()
        for word in ("buy", "sell", "hold", "recommend"):
            assert not re.search(rf"\b{word}\b", report)


class TestNoUnsupportedNumbers:
    def test_every_number_traces_to_the_snapshot(self, any_snapshot):
        report = render_forecast_report(any_snapshot)
        assert find_unsupported_numbers(report, any_snapshot) == []

    def test_detects_invented_price(self, snapshot):
        report = render_forecast_report(snapshot) + "\nUpside target: ₹123456.78\n"
        assert find_unsupported_numbers(report, snapshot) == ["123456.78"]

    def test_detects_invented_probability_and_count(self, snapshot):
        report = render_forecast_report(snapshot) + "\n93.7% chance; 17 of the analysts agree\n"
        assert set(find_unsupported_numbers(report, snapshot)) == {"93.7", "17"}

    def test_detects_invented_small_integers(self, snapshot):
        report = render_forecast_report(snapshot) + "\n37 analysts agree; 88% chance\n"
        assert set(find_unsupported_numbers(report, snapshot)) == {"37", "88"}

    def test_invalidation_trigger_refers_to_target_date_close(self, snapshot):
        report = render_forecast_report(snapshot)
        section = report.split("## Invalidation triggers")[1].split("## Data quality")[0]
        final = snapshot.final_forecast
        assert (
            f"A close on {snapshot.target_date.isoformat()} below ₹{final.p10_price:.2f} "
            f"or above ₹{final.p90_price:.2f}"
        ) in section

    def test_detects_derived_delta(self, snapshot):
        final, quant = snapshot.final_forecast, snapshot.quant_baseline
        delta = (final.prob_up - quant["prob_up"]) * 100 + 0.123
        report = render_forecast_report(snapshot) + f"\nUp probability rose {delta:.3f} points\n"
        assert find_unsupported_numbers(report, snapshot) == [f"{delta:.3f}"]

    def test_render_refuses_unsupported_numbers(self, snapshot, monkeypatch):
        original = report_module._render
        monkeypatch.setattr(
            report_module, "_render", lambda s: original(s) + "\nP50 could reach ₹99999.99\n"
        )
        with pytest.raises(ReportIntegrityError, match="99999.99"):
            render_forecast_report(snapshot)

    def test_graph_report_matches_snapshot_rendering(self, adjusted_state):
        report = adjusted_state.forecast_report
        assert report is not None
        assert report.rstrip().endswith(REQUIRED_DISCLAIMER)
        assert adjusted_state.forecast_id in report
